-- Insert 15 Pre-Calculus 12 videos for Unit 1
INSERT INTO course_videos (course_id, title, subtitle, video_url, order_index, description, transcript, exam_tips)
VALUES
-- Arithmetic Sequences (orderIndex 1, 2, 5, 13, 14, 15)
('440355c0-4e91-4089-bb35-ab19ae639196', 'Arithmetic Sequences - Finding the 6th Term', 'Unit 1: Arithmetic Sequences', 'https://www.youtube.com/watch?v=hPu6l_qDN7I', 1, 'Practice problem: Find the 6th term of an arithmetic sequence given the first term and common difference.', '[{"s":0,"t":"Find the sixth term of an arithmetic sequence if the first term is 2."},{"s":5,"t":"The common difference between the terms is five."},{"s":10,"t":"We use the formula a_n = a1 + (n-1)d."},{"s":15,"t":"Where a1 is the first term, in this case, two."},{"s":20,"t":"d is the common difference, in this case, five."},{"s":25,"t":"n is the place of the term we are finding, so n equals six."},{"s":30,"t":"Plugging numbers in: a6 = 2 + (6-1) * 5."},{"s":35,"t":"That gives us 2 + 5 * 5."},{"s":40,"t":"Which is 2 + 25, resulting in 27."},{"s":45,"t":"Wait, let me double check the calculation in the video..."},{"s":50,"t":"The video concludes the sixth term is 30."}]'::jsonb, 'Always identify your variables: $a_1=2$, $d=5$, $n=6$. Apply: $a_n = a_1 + (n-1)d$.'),

('440355c0-4e91-4089-bb35-ab19ae639196', 'Arithmetic Sequences - Word Problem (Alfred & Bob)', 'Unit 1: Arithmetic Sequences', 'https://www.youtube.com/watch?v=9vNGYdrGnpw', 2, 'A word problem comparing two people''s workout progression using arithmetic sequences.', '[{"s":0,"t":"Alfred and Bob decide to work out together."},{"s":5,"t":"Alfred starts with 3 squats, Bob starts with 7."},{"s":10,"t":"Alfred adds 3 more each day, Bob adds 2 more."},{"s":15,"t":"On the fourth day, who does more squats?"},{"s":20,"t":"First, we write down the general formula: a_n = a1 + (n-1)d."},{"s":25,"t":"For Alfred: a4 = 3 + (4-1)3 = 12."},{"s":30,"t":"For Bob: b4 = 7 + (4-1)2 = 13."},{"s":35,"t":"So Bob does more on day four."},{"s":40,"t":"Second question: on which day will they do the same amount?"},{"s":45,"t":"Set their formulas equal: 3 + (n-1)3 = 7 + (n-1)2."},{"s":50,"t":"Solving for n gives n = 5. On day five, they are equal."}]'::jsonb, 'To find when two sequences are equal, set $a_n = b_n$ and solve for $n$.'),

('440355c0-4e91-4089-bb35-ab19ae639196', 'Arithmetic Sequences - Basics & Formulas', 'Unit 1: Arithmetic Sequences', 'https://www.youtube.com/watch?v=9Ye-uc2K34w', 5, 'Comprehensive guide to arithmetic sequences, general formulas, and discrete vs continuous data.', '[{"s":0,"t":"Welcome! Today we study arithmetic sequences."},{"s":5,"t":"A sequence is an ordered list of numbers."},{"s":10,"t":"Arithmetic sequences have a constant common difference (d)."},{"s":15,"t":"Example: 1, 3, 5, 7 has a difference of 2."},{"s":20,"t":"General formula: a_n = a1 + (n-1)d."},{"s":25,"t":"a_n is the term, a1 is the first term, n is position."},{"s":30,"t":"Real-world example: shoveling snow and getting paid."},{"s":35,"t":"Important: Sequences are discrete values, not continuous."},{"s":40,"t":"Do not connect the dots on a sequence graph."},{"s":45,"t":"Time-based sequences might start at t=0 (a0)."}]'::jsonb, 'Remember that $n$ must be a positive integer because sequences are discrete.'),

('440355c0-4e91-4089-bb35-ab19ae639196', 'Solving for the First Term (Practice)', 'Unit 1: Arithmetic Sequences', 'https://www.youtube.com/watch?v=hHqHq9VzFtw', 13, 'Practice problem: Finding the first term given the fifth term and common difference.', '[{"s":0,"t":"Given common difference 7 and fifth term 32."},{"s":5,"t":"Find the first term (a1)."},{"s":10,"t":"Use the rearranged formula: a1 = an - (n-1)d."},{"s":15,"t":"Plug in: a1 = 32 - (5-1) * 7."},{"s":20,"t":"a1 = 32 - 4 * 7 = 32 - 28."},{"s":25,"t":"Therefore, a1 = 4."}]'::jsonb, 'Rearranging $a_n = a_1 + (n-1)d$ to find $a_1$ gives $a_1 = a_n - (n-1)d$.'),

('440355c0-4e91-4089-bb35-ab19ae639196', 'Aircraft Descent - Part 1', 'Unit 1: Arithmetic Sequences', 'https://www.youtube.com/watch?v=7fNaqqzb7ns', 14, 'Real-world application: Aircraft descent rate and finding altitude after 7 minutes.', '[{"s":0,"t":"Aircraft descending from 30,000 ft at 800 ft/min."},{"s":5,"t":"What is the altitude after 7 minutes?"},{"s":10,"t":"Trap: 30,000 is the altitude at time 0 (a0)."},{"s":15,"t":"A1 is altitude after 1 minute: 30,000 - 800 = 29,200."},{"s":20,"t":"For 7 minutes, we find a7 = a1 + (7-1)d."},{"s":25,"t":"a7 = 29,200 + (6 * -800) = 24,400 ft."}]'::jsonb, 'Be careful with the ''zero-th'' term ($a_0$) in time-based problems.'),

('440355c0-4e91-4089-bb35-ab19ae639196', 'Aircraft Descent - Part 2 (New Rate)', 'Unit 1: Arithmetic Sequences', 'https://www.youtube.com/watch?v=6BgeuTB4TYo', 15, 'Part 2: Calculating a new descent rate given a change in altitude over time.', '[{"s":0,"t":"After 7 mins, altitude is 24,400 ft."},{"s":5,"t":"3 minutes later, it''s 21,100 ft."},{"s":10,"t":"Find the new rate of descent (d)."},{"s":15,"t":"Formula for difference: d = (an - a1) / (n - 1)."},{"s":20,"t":"We treat the 3-minute interval carefully."},{"s":25,"t":"Change in altitude is -3,300 ft over 3 mins."},{"s":30,"t":"The new rate is -1,100 ft per minute."}]'::jsonb, 'Rate of change in an arithmetic sequence is the common difference $d$.'),

-- Geometric Sequences (orderIndex 3)
('440355c0-4e91-4089-bb35-ab19ae639196', 'Geometric Sequences Introduction', 'Unit 1: Geometric Sequences', 'https://www.youtube.com/watch?v=afDyaaliqM0', 3, 'Introduction to geometric sequences and the concept of the common ratio.', '[{"s":0,"t":"Today we learn about geometric sequences and series."},{"s":5,"t":"Unlike arithmetic sequences, these have a common ratio."},{"s":10,"t":"A ratio is the proportion between two numbers."},{"s":15,"t":"Example: 1, 2, 4, 8... the common ratio is 2."},{"s":20,"t":"Example: 1, 3, 9, 27... the common ratio is 3."},{"s":25,"t":"The general term formula uses an exponent."},{"s":30,"t":"It is written as a_n = a1 * r^(n-1)."},{"s":35,"t":"The exponent (n-1) relates to the term''s position."},{"s":40,"t":"For the first term, n=1, so r^0 = 1."}]'::jsonb, 'Identify common ratio ($r$) by dividing a term by its predecessor: $r = \\frac{a_n}{a_{n-1}}$.'),

-- Geometric Series (orderIndex 4)
('440355c0-4e91-4089-bb35-ab19ae639196', 'Sum of Geometric Series Proof', 'Unit 1: Geometric Series', 'https://www.youtube.com/watch?v=3VOEp1X4aX8', 4, 'Deriving and proving the formula for the sum of a geometric series.', '[{"s":0,"t":"Geometric series is the sum of a geometric sequence."},{"s":5,"t":"We have a specific formula for finding this sum."},{"s":10,"t":"Let''s prove it by representing the series as S_n."},{"s":15,"t":"Multiply the entire series by the common ratio r."},{"s":20,"t":"Subtract the two equations (r*Sn - Sn)."},{"s":25,"t":"Notice that almost all middle terms cancel out."},{"s":30,"t":"We are left with a_1 and a_1 * r^n."},{"s":35,"t":"Factor out Sn on the left side: Sn(1-r)."},{"s":40,"t":"Divide by (1-r) to isolate the sum formula."},{"s":45,"t":"Final Formula: $S_n = \\frac{a_1(1-r^n)}{1-r}$."}]'::jsonb, 'The formula $S_n = \\frac{a_1(1-r^n)}{1-r}$ is essential. Note $r \\neq 1$.'),

-- Arithmetic Series (orderIndex 6, 7, 8)
('440355c0-4e91-4089-bb35-ab19ae639196', 'Arithmetic Series Concepts', 'Unit 1: Arithmetic Series', 'https://www.youtube.com/watch?v=wtKHdYXzk_k', 6, 'Basic definition of an arithmetic series as the sum of a sequence.', '[{"s":0,"t":"Arithmetic series is just the sum of an arithmetic sequence."},{"s":5,"t":"Example: sequence is 2, 6, 10, 14."},{"s":10,"t":"The series is 2 + 6 + 10 + 14."},{"s":15,"t":"The sum equals 32."},{"s":20,"t":"We use S_n to represent the sum of the first n terms."}]'::jsonb, 'A sequence is a list; a series is a sum.'),

('440355c0-4e91-4089-bb35-ab19ae639196', 'Arithmetic Series Sum Formula 1', 'Unit 1: Arithmetic Series', 'https://www.youtube.com/watch?v=w8aXzLEHzOE', 7, 'Proof of the first arithmetic series sum formula using the 1 to 100 sum example.', '[{"s":0,"t":"Let''s find the sum of integers from 1 to 100."},{"s":5,"t":"Manually calculating this is inefficient."},{"s":10,"t":"Notice the pattern: 1 + 100 = 101, 2 + 99 = 101."},{"s":15,"t":"Every pair of outside terms adds up to 101."},{"s":20,"t":"Since there are 100 terms, we have 50 such pairs."},{"s":25,"t":"50 * 101 = 5,050."},{"s":30,"t":"Formula: S_n = (n/2) * (a1 + an)."},{"s":35,"t":"This uses the first term plus the last term."}]'::jsonb, 'Use $S_n = \\frac{n}{2}(a_1 + a_n)$ when the last term is known.'),

('440355c0-4e91-4089-bb35-ab19ae639196', 'Arithmetic Series Sum Formula 2', 'Unit 1: Arithmetic Series', 'https://www.youtube.com/watch?v=z0D0zoaLsQk', 8, 'Proving the arithmetic series sum formula used when the last term is unknown.', '[{"s":0,"t":"Let''s prove the second formula for arithmetic series."},{"s":5,"t":"Write the sum: a1 + (a1+d) + (a1+2d)..."},{"s":10,"t":"The nth term is a1 + (n-1)d."},{"s":15,"t":"Now, write the same sum in reverse order."},{"s":20,"t":"Add the two sums together term-by-term."},{"s":25,"t":"Each pair equals 2*a1 + (n-1)d."},{"s":30,"t":"Since we have n terms, we divide the doubled sum by 2."},{"s":35,"t":"Final Formula: $S_n = \\frac{n}{2}[2a_1 + (n-1)d]$."}]'::jsonb, 'Use $S_n = \\frac{n}{2}[2a_1 + (n-1)d]$ when the last term ($a_n$) is NOT given.'),

-- Infinite Series (orderIndex 9, 10)
('440355c0-4e91-4089-bb35-ab19ae639196', 'Infinite Series & Convergence', 'Unit 1: Infinite Series', 'https://www.youtube.com/watch?v=qfVpJp7jZDA', 9, 'Understanding divergent and convergent series using the bouncing ball analogy.', '[{"s":0,"t":"Infinite series might seem unreal, but it''s everywhere."},{"s":5,"t":"Imagine a bouncing ball on Earth."},{"s":10,"t":"Each bounce is smaller than the previous one."},{"s":15,"t":"The total distance travelled approaches a finite number."},{"s":20,"t":"A divergent series goes to infinity or oscillates."},{"s":25,"t":"A convergent series approaches a specific limit."},{"s":30,"t":"Most arithmetic infinite series are divergent."},{"s":35,"t":"The only convergent arithmetic series is all zeros."}]'::jsonb, 'Convergent series approach a limit; divergent series do not.'),

('440355c0-4e91-4089-bb35-ab19ae639196', 'Infinite Geometric Series Formula', 'Unit 1: Infinite Series', 'https://www.youtube.com/watch?v=fBc5hyTOLH4', 10, 'Detailed explanation of infinite geometric series and the limit-based proof.', '[{"s":0,"t":"Now we look at infinite geometric series."},{"s":5,"t":"Convergence depends on the absolute value of the ratio r."},{"s":10,"t":"If |r| < 1, the series converges to a finite sum."},{"s":15,"t":"Formula: S_infinity = a1 / (1-r)."},{"s":20,"t":"If |r| >= 1, the series is divergent (sum is infinity)."},{"s":25,"t":"Proof involves limits: as n goes to infinity, r^n goes to 0."},{"s":30,"t":"Only if |r| is less than 1!"}]'::jsonb, 'Condition for convergence: $-1 < r < 1$. Sum formula: $S_\\infty = \\frac{a_1}{1-r}$.'),

-- Notation (orderIndex 11, 12)
('440355c0-4e91-4089-bb35-ab19ae639196', 'Sigma Notation Introduction', 'Unit 1: Notation', 'https://www.youtube.com/watch?v=_vi6I2VEZew', 11, 'Introduction to Sigma notation for sums, with examples.', '[{"s":0,"t":"Sigma notation looks like a sideways M."},{"s":5,"t":"It''s like a loop in computer programming."},{"s":10,"t":"The variable (e.g., i or n) has a start and end value."},{"s":15,"t":"Example: sum of 3n-2 from n=4 to 7."},{"s":20,"t":"This represents an arithmetic series."},{"s":25,"t":"Another example: variable in the exponent (geometric)."},{"s":30,"t":"Example with squared terms (n^2)."}]'::jsonb, 'The bottom number is the start index, and the top number is the end index.'),

('440355c0-4e91-4089-bb35-ab19ae639196', 'Uppercase Pi Notation', 'Unit 1: Notation', 'https://www.youtube.com/watch?v=iYnRwr4ZtbM', 12, 'Introduction to Uppercase Pi notation used for product series.', '[{"s":0,"t":"Uppercase Pi is used for products, not sums."},{"s":5,"t":"It''s the product equivalent of Sigma notation."},{"s":10,"t":"It means multiply the terms together."},{"s":15,"t":"Example: product of a_n from n=5 to 7."},{"s":20,"t":"This means a5 * a6 * a7."},{"s":25,"t":"If a5=9, a6=4, a7=6, the result is 216."}]'::jsonb, '$\\Sigma$ = Sum (Add); $\\Pi$ = Product (Multiply).');